// Builds the pgTAP parity test for listing_nights from tests/fixtures/availability.json, so the SQL
// function and core/availability.js run the same cases (engineering-constitution.md §7).
// Regenerate after changing the fixture:
//   node tests/fixtures/availability-pgtap.js > supabase/tests/database/08_listing_nights_parity.sql
// tests/unit/availability-parity.test.js fails if the generated file is out of date.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const PARITY_TEST_PATH = 'supabase/tests/database/08_listing_nights_parity.sql';

const q = (v) => (v == null ? 'null' : `'${String(v).replaceAll("'", "''")}'`);
const uuid = (kind, i) => `00000000-0000-0000-00${kind}-${String(i + 1).padStart(12, '0')}`;

export function availabilityPgtap(fixture) {
  const lines = [
    '-- GENERATED by tests/fixtures/availability-pgtap.js from tests/fixtures/availability.json. Do not edit.',
    '-- Parity: listing_nights (SQL) gives the same nights as core/availability.js (BR-AVL-002/003/004).',
    'begin;',
    'create extension if not exists pgtap with schema extensions;',
    `select plan(${fixture.cases.length});`,
    '',
  ];
  fixture.cases.forEach((c, i) => {
    const user = uuid('01', i);
    const listing = uuid('02', i);
    const l = c.listing;
    lines.push(`-- ${c.name}`);
    lines.push(`insert into auth.users (id, email, email_confirmed_at) values (${q(user)}, ${q(`parity${i + 1}@example.com`)}, now());`);
    lines.push(`insert into public.profiles (id, display_name) values (${q(user)}, 'Parity');`);
    if (l.roster) {
      const r = l.roster;
      lines.push(`insert into public.rosters (user_id, days_on, days_off, anchor_date, fly_home_last_day, fly_out_first_day) values (${q(user)}, ${r.daysOn}, ${r.daysOff}, ${q(r.anchor)}, ${r.fliesHomeLastDay}, ${r.fliesOutFirstDay});`);
    }
    lines.push(`insert into public.listings (id, owner_id, availability_type, available_from) values (${q(listing)}, ${q(user)}, ${q(l.availabilityType)}, ${q(l.availableFrom)});`);
    for (const r of l.ranges ?? []) {
      lines.push(`insert into public.listing_availability_ranges (listing_id, start_night, end_exclusive) values (${q(listing)}, ${q(r.startNight)}, ${q(r.endExclusive)});`);
    }
    for (const e of l.exceptions ?? []) {
      lines.push(`insert into public.listing_availability_exceptions (listing_id, night, available) values (${q(listing)}, ${q(e.night)}, ${e.available});`);
    }
    lines.push(`select is(public.listing_nights_at(${q(listing)}, ${q(c.start)}, ${c.n}, ${q(c.today)}), ${q(c.expected)}, ${q(`parity: ${c.name}`)});`);
    lines.push('');
  });
  lines.push('select * from finish();', 'rollback;', '');
  return lines.join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const fixture = JSON.parse(readFileSync(new URL('./availability.json', import.meta.url), 'utf8'));
  process.stdout.write(availabilityPgtap(fixture));
}
